class Solution:
    def zipWords(self, a: str, b: str) -> str:
        i = j = 0
        out = []
        while i < len(a) and j < len(b):
            out.append(a[i] + b[j])
            i += 1
            j += 1
        return "".join(out) + a[i:] + b[j:]

